def cashier_grid(w,cols,offline=False,extra=""):
  b=('<div class="banner" style="background:'+ST['offline']['bg']+';color:'+ST['offline']['fg']+'"><b>⊘</b>Offline sejak 21:14 · timer tetap jalan di TV · 3 aksi menunggu sinkron <span class="grow"></span><span class="btn" style="min-height:32px">Lihat antrean</span></div>') if offline else ''
  filt='<div class="row" style="padding:12px 20px;gap:8px;flex-wrap:wrap">'+'<span class="chip" style="background:var(--hs-ink);color:#fff">Semua 12</span>'+"".join(chip(s,ST[s]['id']+f' {c}') for s,c in [('running',3),('ending',1),('overtime',1),('paused',1),('booked',1),('idle',3)])+'<span class="grow"></span><span class="btn">⌕ Cari unit / member</span><span class="btn p">+ Pesanan F&B</span></div>'
  g=f'<div style="display:grid;grid-template-columns:repeat({cols},1fr);gap:12px;padding:0 20px 20px">'+"".join(tile(u,i==3) for i,u in enumerate(UNITS[:cols*3 if cols<5 else 12]))+'</div>'
  return topbar('<span class="chip" style="background:#E3F1E8;color:#1F5E3A">● Tersambung</span><span class="btn">Booking hari ini · 4</span><span class="btn">Tutup shift</span>')+b+filt+g+extra
